alter table public.transactions add column if not exists subscription_id text null; alter table public.transactions add column if not exists player_id text null; alter table public.transactions add constraint fk_transactions_subscription_id foreign key (subscription_id) references public.subscriptions(id) on delete set null; alter table public.transactions add constraint fk_transactions_player_id foreign key (player_id) references public.players(id) on delete set null; create index if not exists idx_transactions_subscription_id on public.transactions(subscription_id); create index if not exists idx_transactions_player_id on public.transactions(player_id); alter table public.subscriptions drop constraint if exists chk_subscriptions_paid_consistency; alter table public.subscriptions add constraint chk_subscriptions_paid_consistency check ((status = 'paid' and paid_at is not null and coalesce(payment_method,'') <> '') or (status = 'unpaid' and paid_at is null));
